// Auto-generated static font bundle for production Worker runtime
export const STATIC_FONTS_BASE64: Record<string, string> = {
  "SansBold.ttf": "",
  "ScriptElegant.ttf": "",
  "SerifDisplay.ttf": "",
};

const fontCache = new Map<string, Uint8Array>();

export const FONT_ALIASES: Record<string, string> = {
  "sans": "SansBold.ttf",
  "sans.ttf": "SansBold.ttf",
  "sans-regular": "SansBold.ttf",
  "sans-regular.ttf": "SansBold.ttf",
  "sans-bold": "SansBold.ttf",
  "sans-bold.ttf": "SansBold.ttf",
  "sans-italic": "SansBold.ttf",
  "sans-italic.ttf": "SansBold.ttf",
  "sans-bold-italic": "SansBold.ttf",
  "sans-bold-italic.ttf": "SansBold.ttf",
  "sansbold": "SansBold.ttf",
  "sansbold.ttf": "SansBold.ttf",

  "serif": "SerifDisplay.ttf",
  "serif.ttf": "SerifDisplay.ttf",
  "serif-regular": "SerifDisplay.ttf",
  "serif-regular.ttf": "SerifDisplay.ttf",
  "serif-bold": "SerifDisplay.ttf",
  "serif-bold.ttf": "SerifDisplay.ttf",
  "serif-italic": "SerifDisplay.ttf",
  "serif-italic.ttf": "SerifDisplay.ttf",
  "serif-bold-italic": "SerifDisplay.ttf",
  "serif-bold-italic.ttf": "SerifDisplay.ttf",
  "serifdisplay": "SerifDisplay.ttf",
  "serifdisplay.ttf": "SerifDisplay.ttf",

  "script": "ScriptElegant.ttf",
  "script.ttf": "ScriptElegant.ttf",
  "script-regular": "ScriptElegant.ttf",
  "script-regular.ttf": "ScriptElegant.ttf",
  "script-bold": "ScriptElegant.ttf",
  "script-bold.ttf": "ScriptElegant.ttf",
  "script-italic": "ScriptElegant.ttf",
  "script-italic.ttf": "ScriptElegant.ttf",
  "script-bold-italic": "ScriptElegant.ttf",
  "script-bold-italic.ttf": "ScriptElegant.ttf",
  "scriptelegant": "ScriptElegant.ttf",
  "scriptelegant.ttf": "ScriptElegant.ttf",
};

export function getStaticFontBytes(filename: string): Uint8Array | null {
  const normalizedKey = filename.toLowerCase().trim();
  const canonicalFile = FONT_ALIASES[normalizedKey] ?? (STATIC_FONTS_BASE64[filename] ? filename : null);
  if (!canonicalFile) return null;

  if (fontCache.has(canonicalFile)) return fontCache.get(canonicalFile)!;
  const b64 = STATIC_FONTS_BASE64[canonicalFile];
  if (!b64) return null;
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  fontCache.set(canonicalFile, bytes);
  return bytes;
}

